import App from './App.vue';
import './global.css';
// 等待依赖注入的辅助函数
async function waitForDependencies(maxWait = 15000) {
    const checkInterval = 100;
    const startTime = Date.now();
    // 检查关键依赖是否可用
    const getMissingDeps = () => {
        const missing = [];
        if (typeof getCurrentMessageId !== 'function')
            missing.push('getCurrentMessageId');
        if (typeof getChatMessages !== 'function')
            missing.push('getChatMessages');
        if (typeof eventOn !== 'function')
            missing.push('eventOn');
        return missing;
    };
    const checkDeps = () => getMissingDeps().length === 0;
    // 先快速检查一次
    if (checkDeps())
        return;
    // 等待依赖注入
    while (Date.now() - startTime < maxWait) {
        await new Promise(resolve => setTimeout(resolve, checkInterval));
        if (checkDeps())
            return;
    }
    const missing = getMissingDeps();
    console.warn('[状态栏] 等待依赖注入超时，部分功能可能不可用', {
        missing,
        href: window.location?.href,
        referrer: document.referrer,
        hasFrameElement: !!window.frameElement,
    });
}
async function waitForMvuReady(maxWait = 15000) {
    if (typeof Mvu !== 'undefined')
        return true;
    try {
        const topMvu = window.top?.Mvu;
        if (typeof topMvu !== 'undefined' && typeof initializeGlobal === 'function') {
            initializeGlobal('Mvu', topMvu);
        }
    }
    catch {
        // ignore
    }
    if (typeof waitGlobalInitialized === 'function') {
        try {
            await Promise.race([
                waitGlobalInitialized('Mvu'),
                new Promise((_, reject) => {
                    setTimeout(() => reject(new Error('timeout')), maxWait);
                }),
            ]);
        }
        catch {
            // ignore
        }
    }
    else {
        const start = Date.now();
        while (Date.now() - start < maxWait) {
            await new Promise(resolve => setTimeout(resolve, 100));
            if (typeof Mvu !== 'undefined')
                return true;
        }
    }
    return typeof Mvu !== 'undefined';
}
$(async () => {
    // 等待所有依赖注入完成
    await waitForDependencies();
    // 再等待 MVU 框架初始化完成（单独等待，避免把 Mvu 误判为“前置注入失败”）
    const mvuReady = await waitForMvuReady();
    if (!mvuReady) {
        console.warn('[状态栏] 未检测到 Mvu 全局对象，请确认脚本库中的 MVU 脚本已启用', {
            missing: ['Mvu'],
            href: window.location?.href,
            referrer: document.referrer,
            hasFrameElement: !!window.frameElement,
        });
    }
    const scrollToTopOnce = (() => {
        let done = false;
        return () => {
            if (done)
                return;
            done = true;
            const run = () => {
                try {
                    document.documentElement.scrollTop = 0;
                    document.body.scrollTop = 0;
                    window.scrollTo({ top: 0, left: 0, behavior: 'auto' });
                }
                catch {
                    // ignore
                }
            };
            // 多次尝试：覆盖浏览器/iframe恢复滚动、以及首帧布局抖动
            run();
            requestAnimationFrame(run);
            setTimeout(run, 150);
        };
    })();
    // 挂载 Vue 应用
    const app = createApp(App);
    app.use(createPinia());
    app.mount('#app');
    // 进入楼层 iframe 时，总是从顶部开始，避免出现“加载后停在最后一行”
    scrollToTopOnce();
    // BFCache/页面恢复时也强制回到顶部
    window.addEventListener('pageshow', () => {
        scrollToTopOnce();
    }, { once: true });
});
// 卸载时清理资源
$(window).on('pagehide', () => {
    eventClearAll();
});
